def _cites_real_article(outcome: runner.Outcome) -> dict[str, Any]:
    """Every title the answer claims as a source must exist in the corpus.

    Deliberately does not pin a specific article. Retrieval is keyword-based, so
    landing on a different but equally correct article is normal behavior; pinning
    the title would log ordinary retrieval variance as a behavior regression.
    """
    claimed = [
        part.strip(" .*_`")
        for line in SOURCE_LINE.findall(outcome.answer)
        for part in re.split(r"[;,]|\band\b", line)
        if part.strip(" .*_`")
    ]
    if not claimed:
        return _result(False, "no 'Source:' line in the answer")

    real = {title.lower() for title in corpus.article_titles()}
    unknown = [c for c in claimed if not any(c.lower() in r or r in c.lower() for r in real)]
    return _result(
        not unknown,
        f"cited {claimed}" + (f", not in corpus: {unknown}" if unknown else ""),
    )

