import re, pathlib, unicodedata
text = pathlib.Path("ai-discussion/trade-offs.md").read_text()

def slug(heading: str) -> str:
    s = heading.strip().lower()
    s = "".join(c for c in s if c.isalnum() or c in " -_" or unicodedata.category(c).startswith("L"))
