anchors = {slug(h) for h in re.findall(r"^#{2,3} (.+)$", text, re.M)}
used = set(re.findall(r"\]\(#([^)]+)\)", text))
missing = sorted(used - anchors)
print(f"  anchors defined : {len(anchors)}")
print(f"  anchors used    : {len(used)}")
if missing:
    print(f"  BROKEN ({len(missing)}):")
    for m in missing: print(f"    #{m}")
else:
    print("  all internal anchors resolve")
