const fs = require("fs");
const versions = require("/tmp/versions.json");
const LEVERS = ["plan_prompt", "reflect_prompt", "synthesize_prompt", "tool_description"];

// The exact logic from onDraftChange(), run against the real version list.
function selectValue(loadedVersionId, editorValues) {
  const from = versions.find((v) => v.id === loadedVersionId);
  if (from && LEVERS.some((key) => from.config[key] !== editorValues[key])) loadedVersionId = null;
  return loadedVersionId ?? "";
}

const active = versions.find((v) => v.status === "active") || versions[0];
console.log(`  ${versions.length} versions; active = ${active.label} ${active.config_hash}`);

const untouched = { ...active.config };
const edited = { ...active.config, plan_prompt: active.config.plan_prompt + " Be stricter." };
const other = versions[versions.length - 1];

const cases = [
  ["boot: active loaded, nothing typed", active.id, untouched, active.id],
  ["after editing one lever", active.id, edited, ""],
  ["explicitly loaded another version", other.id, { ...other.config }, other.id],
  ["draft with no origin at all", null, untouched, ""],
];

let ok = true;
for (const [name, loaded, values, want] of cases) {
  const got = selectValue(loaded, values);
  const pass = got === want;
  ok = ok && pass;
  const shown = got === "" ? "(unsaved draft)" : got.slice(0, 12);
  console.log(`  [${pass ? "ok " : "FAIL"}] ${name.padEnd(36)} -> ${shown}`);
}

const html = fs.readFileSync("apps/console/web/index.html", "utf8");
const explicitEmpty = html.includes('unsaved.value = "";');
console.log(`\n  placeholder carries an explicit empty value: ${explicitEmpty}`);
process.exit(ok && explicitEmpty ? 0 : 1);

