/* How a transcript looks. Loaded by both /chat and /console from the chatbot's
   static mount, so an answer renders identically wherever you read it. That is
   not tidiness for its own sake: the console exists to judge what the product
   produced, and it cannot do that honestly while displaying it differently.

   Both pages define --accent, --text, --hairline, --surface and --radius before
   this file is used, and custom properties resolve at use time, so the two
   surfaces keep their own palettes and dark mode follows for free. */

:root {
  /* Same percentage, different pigment: the user's turn borrows the accent and
     the assistant's borrows the text colour. Tinting both with the accent would
     have separated them by hue alone, which is the one axis that disappears for
     a colourblind reader; this way they differ in lightness too. Mixed against
     `transparent` rather than a named colour so one declaration composites over
     the paper page on /chat and over the white cards in the console. */
  --msg-user: color-mix(in srgb, var(--accent) 8%, transparent);
  --msg-bot: color-mix(in srgb, var(--text) 8%, transparent);

  /* The two turns lean opposite ways: the question sits against the left edge
     with air on its right, the answer against the right edge with air on its
     left. Colour alone was doing all the work of telling them apart, and a
     tinted box is a weak signal next to the shape of the page. */
  --turn-gap: 12%;
}

.question {
  background: var(--msg-user);
  border-radius: var(--radius);
  padding: 12px 16px;
  margin: 0 var(--turn-gap) 14px 0;
  font-weight: 500;
}

.answer {
  background: var(--msg-bot);
  border-radius: var(--radius);
  padding: 14px 16px;
  margin: 0 0 14px var(--turn-gap);
}

/* Block spacing lives on the children, not on .answer, so a rendered answer
   never opens or closes with a stray gap inside its own box. */
.answer > :first-child { margin-top: 0; }
.answer > :last-child { margin-bottom: 0; }
.answer p { margin: 0 0 12px; }
.answer ul, .answer ol { margin: 0 0 12px; padding-left: 22px; }
.answer li { margin: 3px 0; }
.answer li::marker { color: var(--muted); }
.answer strong { font-weight: 600; }

.answer h2, .answer h3 {
  font-family: "Source Serif 4", Georgia, serif;
  font-weight: 600;
  margin: 20px 0 8px;
  font-size: 1.15em;
}

.answer code {
  background: color-mix(in srgb, var(--text) 6%, transparent);
  padding: 1px 5px;
  border-radius: 4px;
  font-size: 0.9em;
}

/* Citations are links in the Source line itself rather than a separate row of
   chips. There is no third place to look, and nothing to keep in sync with the
   sentence the model actually wrote. */
.answer a {
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--accent);
  text-underline-offset: 2px;
}
.answer a:hover { color: var(--accent); }

// Turning an answer into HTML. Shared by /chat and /console the same way
// answer.css is, and for the same reason: two renderers for one string will
// drift, and a console that displays the product's output differently from the
// product is a poor instrument for judging it.
//
// Hand-written rather than pulling in a markdown library, because there is no
// build step here (TO-22) and the model only ever emits four constructs. It is
// not a markdown implementation and does not try to be -- it covers exactly what
// the synthesize prompt asks for and escapes everything else.

const ANSWER_ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };
const escapeHtml = (s) => String(s).replace(/[&<>]/g, (c) => ANSWER_ESCAPES[c]);
const escapeAttr = (s) => escapeHtml(s).replace(/"/g, "&quot;");

// Must agree with SOURCE_LINE in apps/console/src/driftline/checks.py. That
// check blocks a benchmark case on this line's shape, so if the two disagree
// about what counts as one, the console would be linking a citation line the
// checker just failed the case for.
const SOURCE_LINE = /^\s*sources?\s*:/i;

function answerHtml(text, citations = []) {
  const out = [];
  let list = null;
  const closeList = () => {
    if (list) out.push(`</${list}>`);
    list = null;
  };

  for (const line of String(text ?? "").split("\n")) {
    // Requiring whitespace after the marker is what keeps "**bold at the start
    // of a line**" from being read as a bullet.
    const bullet = line.match(/^\s*[*-]\s+(.*\S)\s*$/);
    const numbered = line.match(/^\s*\d+[.)]\s+(.*\S)\s*$/);
    if (bullet || numbered) {
      const kind = bullet ? "ul" : "ol";
      if (list !== kind) {
        closeList();
        out.push(`<${kind}>`);
        list = kind;
      }
      out.push(`<li>${inlineHtml((bullet || numbered)[1])}</li>`);
      continue;
    }

    closeList();
    const trimmed = line.trim();
    if (!trimmed) continue;

    const heading = trimmed.match(/^(#{2,3})\s+(.*)$/);
    if (heading) {
      const level = heading[1].length;
      out.push(`<h${level}>${inlineHtml(heading[2])}</h${level}>`);
      continue;
    }
    out.push(`<p>${SOURCE_LINE.test(trimmed) ? sourceHtml(trimmed, citations) : inlineHtml(trimmed)}</p>`);
  }

  closeList();
  return out.join("");
}

function inlineHtml(text) {
  return escapeHtml(text)
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/`([^`]+)`/g, "<code>$1</code>");
}

// The model writes "Source: <title>, <title>" as plain prose and has to keep
// doing so: runner._cited() finds the citations by looking for those titles in
// the answer, and _cites_real_article() blocks on the line's exact shape. So the
// links are added here at render time, from the titles the backend already
// resolved to URLs. Longest first, so "Object Consistency" cannot claim part of
// "Character and Object Consistency" -- the same ordering, for the same reason,
// as the citation check itself.
function sourceHtml(line, citations) {
  const spans = [];
  for (const cite of [...citations].sort((a, b) => b.title.length - a.title.length)) {
    const start = line.indexOf(cite.title);
    const end = start + cite.title.length;
    if (start >= 0 && !spans.some(([s, e]) => start < e && end > s)) {
      spans.push([start, end, cite.url]);
    }
  }
  spans.sort((a, b) => a[0] - b[0]);

  let html = "";
  let cursor = 0;
  for (const [start, end, url] of spans) {
    const title = escapeHtml(line.slice(start, end));
    html += inlineHtml(line.slice(cursor, start));
    html += `<a href="${escapeAttr(url)}" target="_blank" rel="noopener">${title}</a>`;
    cursor = end;
  }
  return html + inlineHtml(line.slice(cursor));
}

