         '&family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&display=swap" rel="stylesheet" />')


def inline_style(path: Path) -> str:
    return "\n".join(re.findall(r"<style>(.*?)</style>", path.read_text(), re.S))


