  `answer    left ${{box(a).left.toFixed(0)}}  right ${{box(a).right.toFixed(0)}}   margin-left  ${{cs(a).marginLeft}}`,
  `link      color ${{cs(link).color}}  decoration ${{cs(link).textDecorationLine}}  href ${{link.getAttribute("href")}}`,
  `list item marker present: ${{cs(li).display}} / ${{li.parentElement.tagName}}   strong weight ${{cs(strong).fontWeight}}`,
  `answer white-space  ${{cs(a).whiteSpace}}`,
].join("\\n");
</script></body></html>""")


